css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-oa2wx4 {
				padding: 24px;
				background: #fdfcf9;
			}
			.title.mk-oa2wx4 {
				font-size: 26px;
				font-weight: 700;
				color: #264653;
			}
			.open.mk-oa2wx4 {
				display: block;
				margin-top: 16px;
				padding: 12px 20px;
				border: 2px solid #264653;
				border-radius: 12px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 18px;
			}
			.note.mk-oa2wx4 {
				padding: 24px;
				background: #fdfcf9;
			}
			.heading.mk-oa2wx4 {
				font-size: 24px;
				font-weight: 700;
				color: #264653;
			}
			.body.mk-oa2wx4 {
				margin-top: 12px;
				padding: 12px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				color: #264653;
				font-size: 17px;
			}
			@media (prefers-color-scheme: dark) {
				.page.mk-oa2wx4,
				.note.mk-oa2wx4 {
					background: #1d1b16;
				}
				.title.mk-oa2wx4,
				.heading.mk-oa2wx4 {
					color: #f4f1ea;
				}
				.body.mk-oa2wx4 {
					border-color: #e9c46a;
					color: #e9c46a;
				}
			}
